package com.axiom.analysis.fingerprint; import com.axiom.domain.failure.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.HexFormat; import org.springframework.stereotype.Component;
@Component public class Sha256FailureFingerprinter { public String fingerprint(FailureEventType type,String exception,String message,String root){try{String canonical="v1|"+type+"|"+(exception==null?"":exception)+"|"+message+"|"+(root==null?"":root);return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonical.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} }
